css:
@page {
    size: A4;
    margin: 0;
}
html, body {
    margin: 0;
    padding: 0;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
    font-family: Calibri, sans-serif;
}
.letter-head, #header-html, #footer-html { display: none !important; }
.print-format { padding: 0; margin: 0; }
.bvr-page {
    position: relative;
    width: 210mm;
    min-height: 297mm;
    box-sizing: border-box;
    font-family: Calibri, sans-serif;
    font-size: 13px;
    color: #000;
}
.bvr-bg {
    position: fixed;
    top: 0; left: 0;
    width: 210mm; height: 297mm;
    z-index: 0;
    display: block;
    object-fit: fill;
}
/* Cover the tagline strip with a white bar */
.bvr-tagline-cover {
    position: fixed;
    top: 27mm; left: 0;
    width: 210mm; height: 8mm;
    background: #fff;
    z-index: 1;
}
.bvr-content {
    position: relative;
    z-index: 2;
    padding: 36mm 18mm 30mm 18mm;
    box-sizing: border-box;
}
.bvr-title {
    text-align: center;
    font-size: 17px;
    font-weight: bold;
    margin-bottom: 14px;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: #1a3a5c;
    border-bottom: 2px solid #1a7a6a;
    padding-bottom: 6px;
}
.bvr-meta-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4px 20px;
    margin-bottom: 14px;
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 10px 14px;
    background: #f9fafb;
}
.bvr-meta-row { display: flex; gap: 6px; font-size: 12px; }
.bvr-meta-label { font-weight: 700; color: #555; white-space: nowrap; }
.bvr-section-title {
    font-size: 13px;
    font-weight: 700;
    color: #1a7a6a;
    background: #f0f9f7;
    border-left: 4px solid #1a7a6a;
    padding: 5px 10px;
    margin: 14px 0 6px 0;
    border-radius: 0 4px 4px 0;
}
.bvr-responses-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
    margin-bottom: 10px;
}
.bvr-responses-table th {
    background: #e6f4f1;
    color: #1a3a5c;
    font-weight: 700;
    padding: 5px 8px;
    border: 1px solid #ccc;
    text-align: left;
}
.bvr-responses-table td {
    padding: 4px 8px;
    border: 1px solid #e0e0e0;
    vertical-align: top;
}
.bvr-responses-table tr:nth-child(even) td { background: #f9fafb; }
.bvr-summary-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 10px;
}
.bvr-summary-box {
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 12px;
    font-size: 12px;
}
.bvr-summary-box .bvr-section-title { margin: 0 0 6px 0; font-size: 12px; }
.bvr-summary-box ol { margin: 0; padding-left: 18px; }
.bvr-summary-box ol li { margin-bottom: 3px; }
.bvr-signoff {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-top: 20px;
    padding-top: 14px;
    border-top: 1px solid #ccc;
}
.bvr-signoff-box { font-size: 12px; }
.bvr-signoff-box .bvr-meta-label { display: block; margin-bottom: 4px; }
.bvr-badge {
    display: inline-block;
    padding: 2px 10px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 700;
    background: #e6f4f1;
    color: #1a7a6a;
    border: 1px solid #1a7a6a;
}
.bvr-action-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
    margin-bottom: 10px;
}
.bvr-action-table th {
    background: #e6f4f1;
    color: #1a3a5c;
    font-weight: 700;
    padding: 5px 8px;
    border: 1px solid #ccc;
}
.bvr-action-table td {
    padding: 4px 8px;
    border: 1px solid #e0e0e0;
    vertical-align: top;
}
.bvr-action-table tr:nth-child(even) td { background: #f9fafb; }
